q=p/'READER-NOTES-PROPOSED.json';notes=json.loads(q.read_text()) if q.exists() else [];notes.append({'chapter':7,'slots':[9,10],'da':'På græsk ligner ordene for pest, loimos, og hungersnød, limos, hinanden. Derfor kan man huske orakelverset på to måder. Crawleys engelske oversættelse gengiver ordligheden med death og dearth.','en':'The Greek words for plague (loimos) and famine (limos) differ by one vowel sound. Crawley recreates the resemblance with death and dearth.','status':'editorial note proposed, not inserted into narrator text','source':'Thucydides2.54; local Jones1910 Greek XML'});q.write_text(json.dumps(notes,ensure_ascii=False,indent=2)+'\n')
